"""Automated data quality checks. Results are written to reports/qa_report.md."""
import pandas as pd

from . import config as C


def run_checks(t: dict[str, pd.DataFrame], school: pd.DataFrame, warnings: list[str]) -> str:
    lines = ["# Automated data quality report", "",
             "Generated by `run_pipeline.py`. See DATA_QUALITY_LOG.md for decisions taken.", ""]

    def section(title):
        lines.extend(["", f"## {title}", ""])

    section("File discovery")
    lines += [f"- WARNING: {w}" for w in warnings] or ["- All files recognised and in matching year folders."]

    section("Rows per dataset, district and year")
    counts = pd.DataFrame({k: v.groupby(["district_file", "year"]).size() for k, v in t.items()}).fillna(0).astype(int)
    lines.append(counts.to_markdown())

    section("Duplicate school codes")
    for k in ["profile1", "profile2", "facility", "teacher", "safety"]:  # skips files not downloaded
        if k in t:
            d = t[k].duplicated(["year", "pseudocode"]).sum()
            lines.append(f"- {k}: {d} duplicate school-year rows")

    section("Do all school-level files cover the same schools?")
    lines.append("Compared per year across all files, so state-level and district-level downloads can be mixed.")
    lines.append("")
    required = ["facility", "teacher", "enrolment1"]
    prof = t["profile1"]
    for yr, grp in prof.groupby("year"):
        base = set(grp["pseudocode"])
        for k in required + [k for k in ["profile2"] if k in t]:
            sub = t[k][t[k]["year"] == yr] if k in t else None
            if sub is None or sub.empty:
                if k in required:
                    lines.append(f"- MISSING FILE: {yr} has no {k} data at all")
                continue
            other = set(sub["pseudocode"])
            missing, extra = base - other, other - base
            if missing or extra:
                lines.append(f"- {yr} {k}: {len(missing):,} schools missing, {len(extra):,} unknown schools")
            if len(missing) > 10:  # many missing -> probably whole districts not downloaded
                by_dist = (grp[grp["pseudocode"].isin(missing)]["district"].str.strip().str.upper()
                           .value_counts())
                full = grp["district"].str.strip().str.upper().value_counts()
                whole = [d for d, n in by_dist.items() if n == full[d]]
                if whole:
                    lines.append(f"  - districts with NO {k} rows (download these): {', '.join(sorted(whole))}")
    lines.append("- (only the lines above are problems; small numbers of missing schools are normal)")

    section("Schools per district (from the data itself)")
    lines.append("Use this to spot districts missing in a year, or districts created/abolished between years.")
    lines.append("")
    lines.append(school.pivot_table(index="district", columns="year", values="pseudocode",
                                    aggfunc="count", fill_value=0).to_markdown())

    section("District name in file name vs inside the data")
    single = school[school["district_file"] != school["state"].str.strip().str.upper()]
    mism = single[single["district_file"] != single["district"]]
    lines.append(f"- {len(mism)} rows where they differ")
    if len(mism):
        lines.append(mism.groupby(["district_file", "district"]).size().to_markdown())

    section("Schema changes between years (columns present only in some years)")
    for k, df in t.items():
        years = sorted(df["year"].unique())
        if len(years) < 2:
            lines.append(f"- {k}: only available for {years}")
            continue
        present = {y: set(df.loc[df["year"] == y].dropna(axis=1, how="all").columns) for y in years}
        allc = set.union(*present.values())
        for y in years:
            missing = sorted(allc - present[y])
            if missing:
                lines.append(f"- {k} {y}: {len(missing)} columns absent/empty -> {', '.join(missing[:12])}"
                             + (" ..." if len(missing) > 12 else ""))

    section("Undocumented codes")
    enr = t["enrolment1"]
    extra = sorted(set(enr.loc[enr["item_group"] == C.CWSN_GROUP, "item_id"]) - C.CWSN_DOCUMENTED_IDS)
    lines.append(f"- CWSN item_ids not in schema: {extra or 'none'}")
    unknown_mgmt = sorted(set(school["managment"]) - set(C.MANAGEMENT_GROUP))
    lines.append(f"- Management codes without a group mapping: {unknown_mgmt or 'none'}")

    section("Blocks that look like admin regions, not blocks")
    reg = school[school["block_is_admin_region"]]
    lines.append(reg.groupby(["year", "block", "managment"]).size().rename("schools").to_markdown()
                 if len(reg) else "- none")

    section("Logical consistency")
    fac = t["facility"]
    checks = {
        "functional girls toilets > total girls toilets": fac["total_girls_func_toilet"] > fac["total_girls_toilet"],
        "functional boys toilets > total boys toilets": fac["total_boys_func_toilet"] > fac["total_boys_toilet"],
        "total_class_rooms is 0 but classrooms are reported by condition":
            (fac["total_class_rooms"] == 0) & ((fac["classrooms_in_good_condition"]
             + fac["classrooms_needs_minor_repair"] + fac["classrooms_needs_major_repair"]) > 0),
        "total_class_rooms > 0 but doesn't match classrooms by condition":
            (fac["total_class_rooms"] > 0) & ((fac["classrooms_in_good_condition"]
             + fac["classrooms_needs_minor_repair"] + fac["classrooms_needs_major_repair"])
             != fac["total_class_rooms"]),
    }
    for name, mask in checks.items():
        lines.append(f"- {name}: {int(mask.sum())} rows")
    by_year = school.groupby("year")
    lines.append(by_year[["flag_no_enrolment", "flag_no_teachers_with_students", "flag_high_ptr"]]
                 .sum().to_markdown())

    section("Schools present in only one year")
    yrs = sorted(school["year"].unique())
    for a, b in zip(yrs, yrs[1:]):
        sa = set(school.loc[school["year"] == a, "pseudocode"])
        sb = set(school.loc[school["year"] == b, "pseudocode"])
        lines.append(f"- {a} -> {b}: {len(sa & sb)} in both, {len(sa - sb)} only in {a}, {len(sb - sa)} only in {b}")

    section("Big year-on-year jumps in facility indicators (> 5 percentage points)")
    has = [c for c in school.columns if c.startswith("has_")]
    pct = school[["district", "year"] + has].astype({c: float for c in has}).groupby(["district", "year"]).mean().mul(100)
    jumps = pct.groupby(level=0).diff().abs()
    big = jumps.stack()
    big = big[big > 5]
    lines.append(big.round(1).rename("pp change").to_markdown() if len(big) else "- none")

    return "\n".join(lines) + "\n"